import test from "node:test";
import assert from "node:assert/strict";
import { Gzip, Inflate, gzipSync, strToU8, zipSync } from "fflate";
import { AppError } from "../../lib/app-error.ts";
import { getReadingContext } from "../../lib/diagnostics/reading.ts";
import { textLines, unpack } from "./containers.ts";
import { openConsumerFile } from "./reader.ts";

const dna =
  "# This data file is generated by 23andMe.\n# reference assembly build 37; plus strand\n# rsid\tchromosome\tposition\tgenotype\nrs1\t1\t100\tCT\n";
const ancestry =
  "#AncestryDNA raw data download\n# human reference build 37.1\nrsid\tchromosome\tposition\tallele1\tallele2\nrs1\t1\t100\tC\tT\n";
const vcf =
  "##fileformat=VCFv4.2\n#CHROM\tPOS\tID\tREF\tALT\tQUAL\tFILTER\tINFO\tFORMAT\tSAMPLE\n1\t100\t.\tC\tT\t.\tPASS\t.\tGT\t0/1\n";
const archive = (files: Record<string, string>) =>
  new File(
    [
      zipSync(
        Object.fromEntries(Object.entries(files).map(([name, text]) => [name, strToU8(text)])),
      ),
    ],
    "synthetic.zip",
  );

test("ZIP decompression preserves native capacity failures including Firefox's OOM string", async (t) => {
  const input = archive({ "genome.txt": dna });
  for (const failure of [
    new RangeError("Array buffer allocation failed"),
    new RangeError("Invalid string length"),
    "out of memory",
  ]) {
    await t.test(String(failure), async (t) => {
      // Exercise fflate's catch-and-callback path, which can relay a thrown string.
      t.mock.method(Inflate.prototype, "push", () => {
        throw failure;
      });
      await assert.rejects(unpack(input), (error: unknown) => {
        assert.equal(error, failure);
        if (error instanceof Error) {
          assert.equal(getReadingContext(error).inputContainer, "zip");
          assert.equal(getReadingContext(error).readingStep, "decompress");
        }
        return true;
      });
    });
  }
});

test("ZIP selects one supported genome by its header and ignores README text in either order", async () => {
  for (const content of [dna, "\uFEFF" + ancestry.replaceAll("\n", "\r\n")]) {
    for (const files of [
      { "README.txt": "Read this before opening your download.", "data/genome.txt": content },
      { "data/genome.txt": content, "README.txt": "Read this before opening your download." },
    ]) {
      const source = await openConsumerFile(archive(files));
      assert.equal(source.format, "consumer");
      assert.equal(source.example?.pos, 100);
      assert.deepEqual(source.example?.alleles, ["C", "T"]);
    }
  }
});

test("ZIP and plain TXT accept the same long supported header and detect a second genome", async () => {
  const comments = Array.from({ length: 600 }, () => "# " + "x".repeat(500)).join("\n");
  const content = `# This data file is generated by 23andMe.\n${comments}\n${dna}`;
  assert.ok(content.length > 256 * 1024);
  for (const input of [
    new File([content], "long-header.txt"),
    archive({ "long-header.txt": content, "README.txt": "Instructions" }),
  ]) {
    const source = await openConsumerFile(input);
    assert.equal(source.example?.pos, 100);
    assert.deepEqual(source.example?.alleles, ["C", "T"]);
  }
  for (const files of [
    { "long-header.txt": content, "short-header.txt": dna },
    { "short-header.txt": dna, "long-header.txt": content },
  ])
    await assert.rejects(openConsumerFile(archive(files)), { code: "ARCHIVE_MULTIPLE_DNA" });
});

test("ZIP distinguishes absent and multiple supported DNA payloads without exposing names or text", async () => {
  const probe = "PRIVATE_PROBE_do_not_report";
  const cases = [
    [
      archive({ [`${probe}.txt`]: `# Synthetic cookies\n${probe}`, "README.txt": "Instructions" }),
      "ARCHIVE_NO_DNA",
    ],
    [
      archive({ "README.txt": "# rsid\tchromosome\tposition\tgenotype\nrs1\t1\t100\tCT" }),
      "ARCHIVE_NO_DNA",
    ],
    [
      archive({ "genome.txt": dna, "other.txt": ancestry, "README.txt": "Instructions" }),
      "ARCHIVE_MULTIPLE_DNA",
    ],
    [archive({ "picture.png": "not DNA" }), "ARCHIVE_NO_DNA"],
  ] as const;
  for (const [input, code] of cases) {
    await assert.rejects(openConsumerFile(input), (error: unknown) => {
      assert.ok(error instanceof AppError);
      assert.equal(error.code, code);
      assert.ok(!error.message.includes(probe));
      assert.ok(!JSON.stringify(error).includes(probe));
      return true;
    });
  }
});

test("ZIP-wrapped VCF receives extraction and BGZF guidance", async () => {
  for (const name of [
    "genome.vcf",
    "genome.g.vcf.gz",
    "genome.gvcf.gz",
    "genome.vcf.bgz",
    "genome.txt",
  ]) {
    await assert.rejects(
      openConsumerFile(archive({ [name]: vcf, "README.txt": "Instructions" })),
      (error: unknown) => {
        assert.ok(error instanceof AppError);
        assert.equal(error.code, "ARCHIVE_VCF_UNSUPPORTED");
        assert.match(error.message, /Extract/);
        assert.match(error.message, /bgzip/);
        return true;
      },
    );
  }
});

test("ZIP keeps unsupported DNA hints only when candidate diagnostics agree", async () => {
  const privateText = "SYNTHETIC_PRIVATE_HEADER_FILENAME_AND_DATA";
  const rejected23 = dna.replace("genotype", privateText);
  const rejectedAncestry = ancestry.replace("allele1", privateText);
  for (const files of [
    { [`${privateText}.txt`]: rejected23, "README.txt": "Ordinary instructions" },
    { "one.txt": rejected23, "two.txt": rejected23 },
  ]) {
    await assert.rejects(openConsumerFile(archive(files)), (error: unknown) => {
      assert.ok(error instanceof AppError);
      assert.equal(error.code, "ARCHIVE_NO_DNA");
      const details = { ...getReadingContext(error), ...error.details };
      assert.equal(details.headerProvider, "23andMe");
      assert.equal(details.headerLayout, "other");
      assert.equal(details.formatReason, "columns-mismatch");
      assert.equal(details.readingStep, "select-payload");
      assert.equal(details.inputContainer, "zip");
      assert.equal(JSON.stringify(details).includes(privateText), false);
      return true;
    });
  }
  for (const files of [
    { "one.txt": rejected23, "two.txt": rejectedAncestry },
    { "one.txt": rejectedAncestry, "two.txt": rejected23 },
  ]) {
    await assert.rejects(openConsumerFile(archive(files)), (error: unknown) => {
      assert.ok(error instanceof AppError);
      assert.equal(error.code, "ARCHIVE_NO_DNA");
      const details = { ...getReadingContext(error), ...error.details };
      assert.equal(details.headerProvider, undefined);
      assert.equal(details.headerLayout, undefined);
      assert.equal(details.formatReason, undefined);
      assert.equal(details.inputContainer, "zip");
      return true;
    });
  }
});

test("archive failures identify the failing structural check without byte counts or checksums", async () => {
  const original = gzipSync(strToU8(dna));
  const badSize = original.slice();
  badSize[badSize.length - 4]! ^= 1;
  const badChecksum = original.slice();
  badChecksum[badChecksum.length - 8]! ^= 1;
  for (const [input, container, step, reason] of [
    [new Blob([new Uint8Array([31, 139])]), "gzip", "archive-integrity", "archive-end-missing"],
    [new Blob([badSize]), "gzip", "archive-integrity", "decoded-size-mismatch"],
    [new Blob([badChecksum]), "gzip", "archive-integrity", "checksum-mismatch"],
    [new Blob([new Uint8Array([80, 75])]), "zip", "archive-directory", "archive-end-missing"],
  ] as const) {
    await assert.rejects(unpack(input), (error: unknown) => {
      assert.ok(error instanceof AppError);
      assert.equal(error.code, "ARCHIVE_INVALID");
      assert.deepEqual(
        { ...getReadingContext(error), ...error.details },
        {
          readerKind: "consumer-dna",
          readingStep: step,
          inputContainer: container,
          failureReason: reason,
        },
      );
      return true;
    });
  }
});

test("ZIP validates each candidate checksum separately, including ignored README text", async () => {
  for (const corruptName of ["genome.txt", "README.txt"]) {
    const bytes = new Uint8Array(
      await archive({ "genome.txt": dna, "README.txt": "Instructions" }).arrayBuffer(),
    );
    let changed = false;
    for (let index = 0; index + 46 <= bytes.length; index++) {
      const record = new DataView(bytes.buffer, bytes.byteOffset + index);
      if (record.getUint32(0, true) !== 0x02014b50) continue;
      const length = record.getUint16(28, true);
      const name = new TextDecoder().decode(bytes.subarray(index + 46, index + 46 + length));
      if (name !== corruptName) continue;
      bytes[index + 16]! ^= 1;
      changed = true;
      break;
    }
    assert.ok(changed);
    await assert.rejects(openConsumerFile(new File([bytes], "corrupt.zip")), {
      code: "ARCHIVE_INVALID",
    });
  }
});

test("ZIP rejects undeclared local entries before inflating or reading the rest of the archive", async () => {
  const original = zipSync({ "genome.txt": strToU8(dna) });
  const originalEnd = new DataView(original.buffer, original.byteOffset + original.length - 22);
  const centralOffset = originalEnd.getUint32(16, true);
  for (const extraName of ["extra.txt", "__MACOSX/._extra.txt"]) {
    const extra = zipSync({ [extraName]: new Uint8Array() });
    const extraEnd = new DataView(extra.buffer, extra.byteOffset + extra.length - 22);
    const extraLocal = extra.slice(0, extraEnd.getUint32(16, true));
    const localParts = [
      original.slice(0, centralOffset),
      ...Array<Uint8Array<ArrayBuffer>>(2000).fill(extraLocal),
    ];
    const end = original.slice(-22);
    new DataView(end.buffer).setUint32(
      16,
      localParts.reduce((size, part) => size + part.length, 0),
      true,
    );
    const forged = new Blob([...localParts, original.slice(centralOffset, -22), end]);
    assert.ok(forged.size > 65536);
    const progress: number[] = [];
    await assert.rejects(
      unpack(forged, undefined, (fraction) => progress.push(fraction)),
      { code: "ARCHIVE_INVALID" },
    );
    assert.deepEqual(
      progress,
      [0],
      "reject in the first input chunk, before accumulating undeclared entries",
    );
  }
});

test("ZIP rejects duplicate central or local entry names, even for skipped metadata", async () => {
  for (const names of [
    ["one.txt", "two.txt"],
    ["__MACOSX/._one", "__MACOSX/._two"],
  ]) {
    const [one, two] = names as [string, string];
    for (const signature of [0x02014b50, 0x04034b50]) {
      const bytes = zipSync({ [one]: strToU8(dna), [two]: strToU8(dna) }, { level: 0 });
      let changed = false;
      for (let index = 0; index + 46 <= bytes.length; index++) {
        const record = new DataView(bytes.buffer, bytes.byteOffset + index);
        if (record.getUint32(0, true) !== signature) continue;
        const central = signature === 0x02014b50;
        const nameOffset = index + (central ? 46 : 30);
        const length = record.getUint16(central ? 28 : 26, true);
        const name = new TextDecoder().decode(bytes.subarray(nameOffset, nameOffset + length));
        if (name !== two) continue;
        bytes.set(strToU8(one), nameOffset);
        changed = true;
        break;
      }
      assert.ok(changed);
      const progress: number[] = [];
      await assert.rejects(
        unpack(new Blob([bytes]), undefined, (fraction) => progress.push(fraction)),
        { code: "ARCHIVE_INVALID" },
      );
      assert.deepEqual(progress, signature === 0x02014b50 ? [] : [0]);
    }
  }
});

test("consumer input still rejects empty files and empty gzip payloads", async () => {
  for (const input of [
    new File([], "empty.txt"),
    new File([gzipSync(new Uint8Array())], "empty.gz"),
  ])
    await assert.rejects(openConsumerFile(input), { code: "FILE_EMPTY" });
});

test("consumer input reads original and expanded payloads beyond the former 128 MiB cutoff", async () => {
  const oneMiB = new Uint8Array(1024 * 1024);
  const parts: Uint8Array<ArrayBuffer>[] = [];
  const gzip = new Gzip({ level: 1 }, (chunk) => parts.push(chunk));
  for (let index = 0; index < 129; index++) gzip.push(oneMiB, index === 128);
  const decoded = await unpack(new Blob(parts));
  assert.equal(decoded.size, 129 * 1024 * 1024);
  assert.deepEqual(new Uint8Array(await decoded.slice(-4).arrayBuffer()), new Uint8Array(4));
  // Feed the same large bytes through the plain-file path without another large allocation.
  assert.equal(await unpack(decoded), decoded);
});

test("ZIP still rejects incorrect declared payload sizes without a size cutoff", async () => {
  const bytes = new Uint8Array(await archive({ "genome.txt": dna }).arrayBuffer());
  for (let index = 0; index + 46 <= bytes.length; index++) {
    const record = new DataView(bytes.buffer, bytes.byteOffset + index);
    if (record.getUint32(0, true) === 0x02014b50) {
      record.setUint32(24, 128 * 1024 * 1024 + 1, true);
      break;
    }
  }
  await assert.rejects(unpack(new Blob([bytes])), { code: "ARCHIVE_INVALID" });
});

test("gzip verifies modulo-2^32 decoded size while ZIP retains exact size validation", async () => {
  const input = new Blob([gzipSync(strToU8(dna))]);
  const zip = archive({ "genome.txt": dna });
  const OriginalBlob = globalThis.Blob;
  try {
    // Simulate a decoded Blob over 4 GiB without allocating that much memory.
    globalThis.Blob = class extends OriginalBlob {
      override get size() {
        return super.size + 0x100000000;
      }
    };
    assert.equal((await unpack(input)).size, dna.length + 0x100000000);
    await assert.rejects(unpack(zip), { code: "ARCHIVE_INVALID" });
  } finally {
    globalThis.Blob = OriginalBlob;
  }
});

test("ZIP accepts more than 1000 declared entries while retaining one supported genome", async () => {
  const extras = Object.fromEntries(
    Array.from({ length: 1001 }, (_, index) => [`__MACOSX/._${index}.txt`, "metadata"]),
  );
  const source = await openConsumerFile(archive({ ...extras, "genome.txt": dna }));
  assert.equal(source.example?.pos, 100);
});

test("ZIP selection accepts more than 1000 header comments and long lines", async () => {
  const comments = "# A comment\n".repeat(1001);
  const longLine = `# ${"x".repeat(256 * 1024)}\n`;
  const content = `${comments}${longLine}${dna}`;
  assert.equal(await (await unpack(archive({ "genome.txt": content }))).text(), content);
  const lines: string[] = [];
  for await (const line of textLines(new Blob([longLine + "last line"]))) lines.push(line);
  assert.deepEqual(lines, [longLine.slice(0, -1), "last line"]);
});

test("ZIP aborts after decompression before selecting a DNA payload", async () => {
  const controller = new AbortController();
  const cancelled = new DOMException("Cancelled by test", "AbortError");
  await assert.rejects(
    unpack(
      archive({ "README.txt": "Instructions", "genome.txt": dna }),
      controller.signal,
      (progress) => {
        if (progress === 1) controller.abort(cancelled);
      },
    ),
    (error: unknown) => error === cancelled,
  );
});
